<!--
  Ficheiro: src/components/iptv/StreamLinkEditDialog.vue
  Tipo: Formulário modal Vue.
  Função: Cria e edita fontes da coleção stream_links com validação acessível.
-->
<script setup lang="ts">
import { computed,nextTick,ref,watch } from "vue";import { streamLinkRepository } from "@/domain/repositories";import { findDuplicateLink } from "@/domain/iptv/linkDuplicate";import { createLinkForm,linkFormHasErrors,validateStreamLinkForm,type StreamLinkFormErrors } from "@/domain/iptv/linkValidation";import type { ChannelRecord,StreamLinkRecord } from "@/types/records";
const props=defineProps<{channel:ChannelRecord|null;link:StreamLinkRecord|null;open:boolean}>();const emit=defineEmits<{close:[];saved:[StreamLinkRecord]}>();const form=ref(createLinkForm());const errors=ref<StreamLinkFormErrors>({});const submitError=ref("");const saving=ref(false);const first=ref<HTMLInputElement|null>(null);const entries=computed(()=>Object.entries(errors.value));watch(()=>[props.open,props.link] as const,async([open])=>{if(open){form.value=createLinkForm(props.link);errors.value={};submitError.value="";await nextTick();first.value?.focus()}},{immediate:true});async function save(){if(!props.channel)return;const validation=validateStreamLinkForm(form.value);errors.value=validation;submitError.value="";await nextTick();if(linkFormHasErrors(validation)){document.getElementById(`stream-link-${Object.keys(validation)[0]}`)?.focus();return}saving.value=true;try{if(await findDuplicateLink(props.channel.id,form.value.url,props.link?.id)){submitError.value="Já existe uma fonte com o mesmo endereço neste canal.";return}const payload={canal_tv:props.channel.id,stream:"",url:form.value.url.trim(),rotulo:form.value.rotulo.trim(),tipo:form.value.tipo,qualidade:form.value.qualidade,prioridade:form.value.prioridade,ativo:form.value.ativo,referrer:form.value.referrer.trim(),user_agent:form.value.user_agent.trim()};const saved=props.link?await streamLinkRepository.update(props.link.id,payload):await streamLinkRepository.create(payload);emit("saved",saved as StreamLinkRecord)}catch(c){submitError.value=c instanceof Error?c.message:String(c)}finally{saving.value=false}}
</script>
<template><Teleport to="body"><div v-if="open&&channel" class="dialog-backdrop" @click.self="!saving&&emit('close')"><section class="dialog-panel stream-link-edit" role="dialog" aria-modal="true" aria-labelledby="stream-link-edit-title" @keydown.esc.prevent="!saving&&emit('close')"><form novalidate @submit.prevent="save"><div class="dialog-header"><div><p class="eyebrow">{{channel.nome}}</p><h2 id="stream-link-edit-title">{{link?'Editar fonte':'Adicionar fonte'}}</h2></div><button class="icon-button" type="button" aria-label="Fechar" :disabled="saving" @click="emit('close')">×</button></div><div v-if="entries.length" class="form-error-summary" role="alert" aria-live="assertive"><h3>Corrige os campos assinalados</h3><ul><li v-for="[field,message] in entries" :key="field"><button type="button" @click="document.getElementById(`stream-link-${field}`)?.focus()">{{message}}</button></li></ul></div><div v-if="submitError" class="form-alert form-alert-error" role="alert">{{submitError}}</div><div class="form-grid"><label class="form-field field-wide"><span>URL *</span><input id="stream-link-url" ref="first" v-model.trim="form.url" :aria-invalid="errors.url?'true':'false'" :aria-describedby="errors.url?'stream-link-url-error':undefined"/><small v-if="errors.url" id="stream-link-url-error" class="field-error" role="alert">{{errors.url}}</small></label><label class="form-field"><span>Rótulo</span><input id="stream-link-rotulo" v-model="form.rotulo" maxlength="200"/><small v-if="errors.rotulo" class="field-error">{{errors.rotulo}}</small></label><label class="form-field"><span>Tipo</span><select v-model="form.tipo"><option value="hls">HLS</option><option value="dash">MPEG-DASH</option><option value="http">HTTP</option><option value="audio">Áudio</option><option value="rtmp">RTMP</option><option value="rtsp">RTSP</option><option value="udp">UDP/RTP</option><option value="outro">Outro</option></select></label><label class="form-field"><span>Qualidade</span><select v-model="form.qualidade"><option>Desconhecida</option><option>Audio</option><option>SD</option><option>HD</option><option>FHD</option><option>4K</option></select></label><label class="form-field"><span>Prioridade</span><input id="stream-link-prioridade" v-model.number="form.prioridade" type="number" min="0" step="1"/><small v-if="errors.prioridade" class="field-error">{{errors.prioridade}}</small></label><label class="check-field"><input v-model="form.ativo" type="checkbox"/> Fonte ativa</label><label class="form-field field-wide"><span>Referrer</span><input id="stream-link-referrer" v-model.trim="form.referrer" maxlength="2000"/><small v-if="errors.referrer" class="field-error">{{errors.referrer}}</small></label><label class="form-field field-wide"><span>User agent</span><textarea id="stream-link-user_agent" v-model="form.user_agent" rows="3" maxlength="500"/><small v-if="errors.user_agent" class="field-error">{{errors.user_agent}}</small></label></div><p v-if="form.referrer||form.user_agent||['rtmp','rtsp','udp'].includes(form.tipo)" class="field-warning" role="status">Esta fonte requer reprodução ou teste através do backend local.</p><div class="form-actions"><button class="button button-secondary" type="button" :disabled="saving" @click="emit('close')">Cancelar</button><button class="button button-primary" type="submit" :disabled="saving" :aria-busy="saving">{{saving?'A guardar…':'Guardar fonte'}}</button></div></form></section></div></Teleport></template>
